// newTaskCard builds a 44px high inner task card.
func newTaskCard(parent *qt.QWidget, objectName string) *widgets.CardWidget {
	card := widgets.NewCardWidget(parent)
	card.SetMinimumSize2(0, 44)
	card.SetMaximumSize2(16777215, 44)
	card.SetObjectName(objectName)
	return card
}

// configureTaskIcon sizes an inner task icon widget.
func configureTaskIcon(icon *widgets.IconWidget, objectName string) {
	icon.SetMinimumSize2(16, 16)
	icon.SetMaximumSize2(16, 16)
	icon.SetObjectName(objectName)
}

// addTaskRow builds the layout of a single inner task row.
func addTaskRow(card *widgets.CardWidget, icon *widgets.IconWidget, label **widgets.BodyLabel, objectName string, strikeOut bool) {
	hLayout9 := qt.NewQHBoxLayout(card.QWidget)
	hLayout9.SetContentsMargins(15, -1, -1, -1)

	hLayout8 := qt.NewQHBoxLayout2()
	hLayout8.AddWidget(icon.QWidget)
	hLayout9.AddLayout(hLayout8.QLayout)

	l := widgets.NewBodyLabelText("", card.QWidget)
	l.SetProperty("pixelFontSize", qt.NewQVariant7(14))
	if strikeOut {
		l.SetProperty("strikeOut", qt.NewQVariant11(true))
	}
	l.SetObjectName(objectName)
	*label = l
	hLayout9.AddWidget(l.QWidget)
	hLayout9.AddStretchWithStretch(1)
}

// setShadowEffect attaches a soft drop shadow to a card.
func setShadowEffect(card *qt.QWidget) {
	effect := qt.NewQGraphicsDropShadowEffect2(card.QObject)
	effect.SetColor(qt.NewQColor11(0, 0, 0, 15))
	effect.SetBlurRadius(10)
	effect.SetOffset2(0, 0)
	card.SetGraphicsEffect(effect.QGraphicsEffect)
}
